INSERT INTO `verses` (`book_id`, `chapter`, `verse`, `text`) VALUES
(2, 12, 48, 'Mas si algÃºn extranjero peregrinare contigo, y quisiere hacer la pascua a JehovÃ¡, sÃ©ale circuncidado todo varÃ³n, y entonces se llegarÃ¡ a hacerla, y serÃ¡ como el natural de la tierra; pero ningÃºn incircunciso comerÃ¡ de ella.'),
