INSERT INTO `verses` (`book_id`, `chapter`, `verse`, `text`) VALUES
(24, 32, 8, 'Y vino a mÃ­ Hanameel, hijo de mi tÃ­o, conforme a la palabra de JehovÃ¡, al patio de la cÃ¡rcel, y dÃ­jome: Compra ahora mi heredad que estÃ¡ en Anathoth, en tierra de BenjamÃ­n, porque tuyo es el derecho de la herencia, y a ti compete la redenciÃ³n: cÃ³mprala para ti. Entonces conocÃ­ que era palabra de JehovÃ¡.'),
