INSERT INTO `verses` (`book_id`, `chapter`, `verse`, `text`) VALUES
(40, 26, 17, 'Y el primer dÃ­a de la fiesta de los panes sin levadura, vinieron los discÃ­pulos a JesÃºs, diciÃ©ndole: Â¿DÃ³nde quieres que aderecemos para ti para comer la pascua?'),
