INSERT INTO `verses` (`book_id`, `chapter`, `verse`, `text`) VALUES
(58, 6, 6, 'Y recayeron, sean otra vez renovados para arrepentimiento, crucificando de nuevo para sÃ­ mismos al Hijo de Dios, y exponiÃ©ndole a vituperio.'),
